"use client";

import * as React from "react";
import styles from "../styles/morphing-border.module.css";

export interface MorphingBorderProps extends React.HTMLAttributes<HTMLDivElement> {
  /** Heading text */
  title?: string;
  /** Supporting copy */
  subtitle?: string;
  /** Primary traveling beam color */
  primaryColor?: string;
  /** Secondary traveling beam color */
  secondaryColor?: string;
  /** Orbit cycle duration in seconds */
  speed?: number;
  /** Corner radius in pixels */
  borderRadius?: number;
  /** Border thickness in pixels */
  borderWidth?: number;
}

export function MorphingBorder({
  title = "Traveling Perimeter Outline",
  subtitle = "Continuous conic beam paired with subtle corner-radius modulation and zero layout thrashing.",
  primaryColor = "#f4f4f6",
  secondaryColor = "#60a5fa",
  speed = 4.2,
  borderRadius = 14,
  borderWidth = 1.5,
  children,
  className = "",
  ...rest
}: MorphingBorderProps) {
  const customStyle = {
    "--mf-mb-primary": primaryColor,
    "--mf-mb-secondary": secondaryColor,
    "--mf-mb-speed": `${speed}s`,
    "--mf-mb-radius": `${borderRadius}px`,
    "--mf-mb-width": `${borderWidth}px`,
  } as React.CSSProperties;

  return (
    <div style={customStyle} className={`${styles.outer} ${className}`.trim()} {...rest}>
      <div aria-hidden="true" className={styles.travelingBeam} />
      <div className={styles.inner}>
        <h3 className={styles.title}>{title}</h3>
        <p className={styles.subtitle}>{subtitle}</p>
        {children}
      </div>
    </div>
  );
}

.outer {
  position: relative;
  overflow: hidden;
  padding: var(--mf-mb-width, 1.5px);
  border-radius: var(--mf-mb-radius, 14px);
  background-color: #252530;
  animation: mfMorphRadius calc(var(--mf-mb-speed, 4.2s) * 1.5) ease-in-out infinite alternate;
}

.travelingBeam {
  pointer-events: none;
  position: absolute;
  inset: -120%;
  background: conic-gradient(
    from 0deg,
    transparent 0deg 230deg,
    var(--mf-mb-secondary, #60a5fa) 295deg,
    var(--mf-mb-primary, var(--mf-fg, #f4f4f6)) 348deg,
    transparent 360deg
  );
  animation: mfBorderOrbit var(--mf-mb-speed, 4.2s) linear infinite;
}

.inner {
  position: relative;
  z-index: 1;
  border-radius: calc(var(--mf-mb-radius, 14px) - var(--mf-mb-width, 1.5px));
  background-color: var(--mf-bg, #0d0d12);
  padding: 1.45rem;
  color: var(--mf-fg, #f4f4f6);
}

.title {
  margin: 0 0 0.45rem 0;
  font-size: 1.025rem;
  font-weight: 600;
  letter-spacing: -0.02em;
}

.subtitle {
  margin: 0;
  font-size: 0.85rem;
  line-height: 1.55;
  color: var(--mf-muted, #a1a1aa);
}

@keyframes mfBorderOrbit {
  to {
    transform: rotate(360deg);
  }
}

@keyframes mfMorphRadius {
  0% {
    border-radius: var(--mf-mb-radius, 14px);
  }
  100% {
    border-radius: calc(var(--mf-mb-radius, 14px) + 6px);
  }
}

@media (prefers-reduced-motion: reduce) {
  .outer,
  .travelingBeam {
    animation: none;
  }
}

